// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.34;

/// @title ICollateralToken
/// @author Polymarket
/// @notice Interface for the Polymarket collateral token (ERC-20) that supports minting, burning,
/// and wrapping/unwrapping underlying assets
interface ICollateralToken {
    /// @notice Mints collateral tokens to a recipient
    /// @param _to The address to receive the minted tokens
    /// @param _amount The amount of tokens to mint
    function mint(address _to, uint256 _amount) external;

    /// @notice Burns collateral tokens from the caller
    /// @param _amount The amount of tokens to burn
    function burn(uint256 _amount) external;

    /// @notice Wraps a supported underlying asset into collateral tokens
    /// @dev The underlying asset must be transferred into the contract before this call or during
    ///      the callback.
    /// @param _asset The address of the underlying asset to wrap
    /// @param _to The address to receive the minted collateral tokens
    /// @param _amount The amount of the underlying asset to wrap
    /// @param _callbackReceiver The address to receive a wrap callback, or address(0) to skip
    /// @param _data Arbitrary data forwarded to the callback receiver
    function wrap(address _asset, address _to, uint256 _amount, address _callbackReceiver, bytes calldata _data)
        external;

    /// @notice Unwraps collateral tokens back into a supported underlying asset
    /// @dev Collateral tokens must be transferred into the contract before this call or during the
    ///      callback.
    /// @param _asset The address of the underlying asset to receive
    /// @param _to The address to receive the unwrapped underlying asset
    /// @param _amount The amount of collateral tokens to unwrap
    /// @param _callbackReceiver The address to receive an unwrap callback, or address(0) to skip
    /// @param _data Arbitrary data forwarded to the callback receiver
    function unwrap(address _asset, address _to, uint256 _amount, address _callbackReceiver, bytes calldata _data)
        external;
}

// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.34;

/// @title ICollateralTokenCallbacks
/// @author Polymarket
/// @notice Callback interface that receivers must implement to participate in CollateralToken
///         wrap/unwrap flows.
/// @dev The CollateralToken invokes these callbacks during wrap and unwrap operations when a
///      non-zero callback receiver is specified.
interface ICollateralTokenCallbacks {
    /// @notice Called by the CollateralToken during a wrap operation before the underlying asset is
    ///         transferred to the vault.
    /// @dev Implementations should transfer the required underlying asset into the CollateralToken
    ///      within this callback.
    /// @param _asset The address of the underlying asset being wrapped
    /// @param _to The address that received the minted collateral tokens
    /// @param _amount The amount of the underlying asset being wrapped
    /// @param _data Arbitrary data forwarded from the original wrap call
    function wrapCallback(address _asset, address _to, uint256 _amount, bytes calldata _data) external;

    /// @notice Called by the CollateralToken during an unwrap operation before collateral tokens
    ///         are burned.
    /// @dev Implementations should transfer the required collateral tokens into the
    ///      CollateralToken within this callback.
    /// @param _asset The address of the underlying asset being unwrapped
    /// @param _to The address that received the unwrapped underlying asset
    /// @param _amount The amount of collateral tokens being burned
    /// @param _data Arbitrary data forwarded from the original unwrap call
    function unwrapCallback(address _asset, address _to, uint256 _amount, bytes calldata _data) external;
}
